const body = $json.body ?? $json;
const data = body.data ?? body;
const key = data.key ?? {};
const message = data.message ?? {};

const remoteJid = String(key.remoteJid ?? '');
const telefone = remoteJid.replace(/@.*$/, '').replace(/\D/g, '');
const fromMe = Boolean(key.fromMe);
const isGroup = remoteJid.endsWith('@g.us');

let mensagem = '';
let mensagem_de_audio = '';
let has_audio = false;
if (message.conversation) mensagem = message.conversation;
else if (message.extendedTextMessage?.text) mensagem = message.extendedTextMessage.text;
else if (message.audioMessage) { mensagem_de_audio = JSON.stringify(message.audioMessage); has_audio = true; }
else if (message.imageMessage?.caption) mensagem = message.imageMessage.caption;

const instance = String(body.instance ?? data.instance ?? '');
const pushName = String(data.pushName ?? '');
const idMensagem = String(key.id ?? `m-${Date.now()}`);
const timestamp = Number(data.messageTimestamp ?? Math.floor(Date.now()/1000));

return [{
  json: {
    instancia: instance,
    telefone,
    fromMe,
    is_group: isGroup,
    mensagem,
    mensagem_de_audio,
    has_audio,
    pushName,
    id_mensagem: idMensagem,
    timestamp,
    remoteJid
  }
}];

const ultima = $input.last();
const meuId = $('Info').first().json.id_mensagem;
if (!ultima || ultima.json.id_mensagem !== meuId) {
  // Mensagem encavalada - outro workflow vai processar
  return [];
}
// Pass-through todas as mensagens da fila
return $input.all();

const items = $input.all();
const textos = items.map(i => i.json.mensagem).filter(Boolean);
return [{ json: { mensagem_consolidada: textos.join(' \n ') } }];

const produtos = $input.all().map(i => i.json);
const cliente = $('Upsert Cliente (RAG)').first().json;
const pizzaria = $('Carregar Pizzaria').first().json;
const info = $('Info').first().json;
const msg = $('Consolidar mensagens').first().json.mensagem_consolidada;

const byCat = {};
for (const p of produtos) {
  const cat = p.categoria || 'outro';
  if (!byCat[cat]) byCat[cat] = [];
  byCat[cat].push(`- ${p.nome} (R$ ${Number(p.preco).toFixed(2)}) [id:${p.id}]${p.arquivo_drive_id ? ` [drive:${p.arquivo_drive_id}]` : ''}${p.descricao ? ` - ${p.descricao}` : ''}`);
}
let cardapio = '';
for (const cat of Object.keys(byCat).sort()) {
  cardapio += `\n## ${cat.toUpperCase()}\n${byCat[cat].join('\n')}\n`;
}
if (!cardapio.trim()) cardapio = '(card?pio vazio)';

let ragContext = '';
if (cliente?.total_pedidos > 0) {
  ragContext = `\n\nCLIENTE RECORRENTE:\nNome: ${cliente.nome || 'sem nome'}\nEndere?o padr?o: ${cliente.endereco_padrao || 'n?o informado'}\nPrefer?ncias: ${cliente.preferencias || 'nenhuma'}\nTotal de pedidos: ${cliente.total_pedidos} | Total gasto: R$ ${Number(cliente.total_gasto||0).toFixed(2)}\n?ltima visita: ${cliente.ultima_visita || 'nunca'}`;
  if (Array.isArray(cliente.historico_pedidos) && cliente.historico_pedidos.length) {
    const last = cliente.historico_pedidos.slice(-3).map(h => `. ${h.date || ''}: ${h.items || ''} (R$ ${Number(h.total||0).toFixed(2)})`).join('\n');
    ragContext += `\n?ltimos pedidos:\n${last}`;
  }
} else {
  ragContext = `\n\nCLIENTE NOVO: primeiro contato (telefone ${info.telefone}).`;
}

const basePrompt = pizzaria.prompt_personalizado || 'Voc? ? o PizzaBot, assistente virtual da pizzaria. Seja simp?tico, r?pido e ajude o cliente a fechar o pedido.';

const systemMessage = `${basePrompt}\n\n## CARD?PIO DISPON?VEL${cardapio}\n${ragContext}\n\nINSTRU??ES:\n- Use APENAS itens do card?pio acima (j? filtrado por dispon?veis).\n- Ao confirmar o pedido use a tool Registrar_Pedido passando o array de itens com {nome, qtd, preco_unit}.\n- Apos registrar, se o cliente quiser pagar via PIX/cartao, use Gerar_Pagamento_PIX com o id retornado pelo Registrar_Pedido.\n- O workflow de pagamento envia o link/PIX em mensagem separada; na sua resposta principal, apenas confirme o pedido e diga que o PIX/link sera enviado.\n- Se Gerar_Pagamento_PIX retornar ok=false, nao diga que o pagamento automatico esta desativado; diga que a equipe vai conferir o pagamento e acione Escalar_Humano.\n- Use Escalar_Humano se o cliente pedir falar com atendente.\n- Use Atualizar_Obs_Pedido para adicionar observa??es ao pedido j? registrado.\n- Use Enviar_Cardapio_Arquivo passando o file_id do produto (campo arquivo_drive_id) quando o cliente pedir uma imagem do produto.\n- Use Lembrar_Cliente para salvar nome/endere?o/prefer?ncias do cliente quando identificados.\n- Sempre confirme endere?o de entrega antes de registrar o pedido.`;

return [{
  json: {
    systemMessage,
    userMessage: msg || info.mensagem || '',
    sessionId: `${pizzaria.id}-${info.telefone}`,
    pizzaria_id: pizzaria.id,
    cliente_id: cliente.id,
    telefone: info.telefone,
    instancia: info.instancia,
    has_audio: info.has_audio
  }
}];

const texto = ($input.first().json.text || '').trim();

// 1) divide em parágrafos (double newline) — forma mais natural no WhatsApp
let partes = texto.split(/\n\n+/).map(p => p.trim()).filter(p => p.length > 0);

// 2) se bloco único muito longo, agrupa frases de 2 em 2
if (partes.length === 1 && partes[0].length > 280) {
  const frases = partes[0].match(/[^.!?]+[.!?]+\s*/g);
  if (frases && frases.length > 1) {
    const agrupadas = [];
    for (let i = 0; i < frases.length; i += 2) {
      agrupadas.push((frases[i] + (frases[i+1] || '')).trim());
    }
    partes = agrupadas.filter(p => p.length > 0);
  }
}

const instancia = $('Info').first().json.instancia;
const telefone  = $('Info').first().json.telefone;

// delay proporcional: ~55ms/char, min 0.8s, max 5s
return partes.map((parte, i) => ({
  json: {
    texto: parte,
    delay_s: Math.round(Math.min(Math.max(parte.length * 0.055, 0.8), 5) * 10) / 10,
    indice: i + 1,
    total: partes.length,
    instancia,
    telefone,
  }
}));

